func (this *P2b) ParseMarket(market any) map[string]any {
	var marketId *string = this.SafeString(market, "name")
	var baseId *string = this.SafeString(market, "stock")
	var quoteId *string = this.SafeString(market, "money")
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	if (base == nil) || (quote == nil) {
		return nil
	}
	var limits map[string]any = SafeMapTyped(market, "limits")
	var maxAmount *string = this.SafeString(limits, "max_amount")
	var maxPrice *string = this.SafeString(limits, "max_price")
	return map[string]any{
		"id":             marketId,
		"symbol":         *base + "/" + *quote,
		"base":           base,
		"quote":          quote,
		"settle":         nil,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       nil,
		"type":           "spot",
		"spot":           true,
		"margin":         false,
		"swap":           false,
		"future":         false,
		"option":         false,
		"active":         true,
		"contract":       false,
		"linear":         nil,
		"inverse":        nil,
		"contractSize":   nil,
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.SafeNumber(limits, "step_size"),
			"price":  this.SafeNumber(limits, "tick_size"),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.SafeNumber(limits, "min_amount"),
				"max": this.ParseNumber(this.OmitZero(maxAmount)),
			},
			"price": map[string]any{
				"min": this.SafeNumber(limits, "min_price"),
				"max": this.ParseNumber(this.OmitZero(maxPrice)),
			},
			"cost": map[string]any{
				"min": this.SafeNumber(limits, "min_total"),
				"max": nil,
			},
		},
		"created": nil,
		"info":    market,
	}
}

