func (this *P2b) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	if typeVar == "market" {
		panic(BadRequest(this.Id + " createOrder () can only accept orders with type \"limit\""))
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"market": market["id"],
		"side":   side,
		"amount": this.AmountToPrecision(symbol, amount),
		"price":  this.PriceToPrecision(symbol, price),
	}

	r1 := <-this.PrivatePostOrderNew(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//    {
	//        "success": true,
	//        "errorCode": "",
	//        "message": "",
	//        "result": {
	//            "orderId": 171906478744,          // Order id
	//            "market": "ETH_BTC",              // Market name
	//            "price": "0.04348",               // Price
	//            "side": "buy",                    // Side
	//            "type": "limit",                  // Order type
	//            "timestamp": 1698484861.746517,   // Order creation time
	//            "dealMoney": "0",                 // Filled total
	//            "dealStock": "0",                 // Filled amount
	//            "amount": "0.0277",               // Original amount
	//            "takerFee": "0.002",              // taker fee
	//            "makerFee": "0.002",              // maker fee
	//            "left": "0.0277",                 // Unfilled amount
	//            "dealFee": "0"                    // Filled fee
	//        }
	//    }
	//
	var result map[string]any = SafeMapTyped(response, "result")

	ch <- AsyncResult[Order]{Value: this.ParseOrder(result, market)}
	return nil
}

